package main

import "sort"

type Set[T comparable] map[T]bool

func cloneSet[T comparable](source Set[T]) Set[T] {
	out := Set[T]{}
	for value := range source {
		out[value] = true
	}
	return out
}
func equalSet[T comparable](a, b Set[T]) bool {
	if len(a) != len(b) {
		return false
	}
	for value := range a {
		if !b[value] {
			return false
		}
	}
	return true
}
func unionInto[T comparable](a, b Set[T]) {
	for value := range b {
		a[value] = true
	}
}
func intersectInto[T comparable](a, b Set[T]) {
	for value := range a {
		if !b[value] {
			delete(a, value)
		}
	}
}
func sortedInts(set Set[int]) []int {
	out := []int{}
	for value := range set {
		out = append(out, value)
	}
	sort.Ints(out)
	return out
}
func sortedStrings(set Set[string]) []string {
	out := []string{}
	for value := range set {
		out = append(out, value)
	}
	sort.Strings(out)
	return out
}

type Block struct {
	Number, First, Last, Start, End, IDom, Depth int
	Labels                                       []string
	Predecessors, Successors                     []int
	Dom                                          Set[int]
	Reachable                                    bool
}
type Loop struct {
	Header                 int
	Latches                []int
	Blocks, Exits, Outside Set[int]
	Depth                  int
}
type CFG struct {
	Function                    *Function
	Blocks                      []*Block
	Instructions                []*Instruction
	BlockOf, Positions          map[int]int
	Postorder, ReversePostorder []int
	Reachable                   Set[int]
	Loops                       []*Loop
}

func newCFG(f *Function) *CFG {
	g := &CFG{Function: f, Blocks: []*Block{nil}, Instructions: []*Instruction{nil}, BlockOf: map[int]int{}, Positions: map[int]int{}, Reachable: Set[int]{}}
	pending := []string{}
	pendingStart := 0
	var current *Block
	var previous *Instruction
	for i, line := range f.Code {
		if line.Instruction == nil {
			if len(pending) == 0 {
				pendingStart = i
			}
			pending = append(pending, line.Label)
			continue
		}
		s := line.Instruction
		number := len(g.Instructions)
		s.Number = number
		g.Instructions = append(g.Instructions, s)
		g.Positions[number] = i
		if current == nil || len(pending) > 0 || previous.Kind == "goto" || previous.Kind == "if" || previous.Kind == "return" {
			start := i
			if len(pending) > 0 {
				start = pendingStart
			}
			if current != nil {
				current.End = start
			}
			current = &Block{Number: len(g.Blocks), First: number, Last: number, Start: start, Labels: append([]string{}, pending...)}
			g.Blocks = append(g.Blocks, current)
		} else {
			current.Last = number
		}
		pending = nil
		g.BlockOf[number] = current.Number
		previous = s
	}
	current.End = len(f.Code)
	labels := map[string]int{}
	for _, b := range g.Blocks[1:] {
		for _, label := range b.Labels {
			labels[label] = b.Number
		}
	}
	for _, b := range g.Blocks[1:] {
		s := g.Instructions[b.Last]
		switch s.Kind {
		case "goto":
			b.Successors = []int{labels[s.Name]}
		case "if":
			b.Successors = []int{b.Number + 1}
			if target := labels[s.Name]; target != b.Number+1 {
				b.Successors = append(b.Successors, target)
			}
		case "return":
		default:
			b.Successors = []int{b.Number + 1}
		}
		for _, next := range b.Successors {
			g.Blocks[next].Predecessors = append(g.Blocks[next].Predecessors, b.Number)
		}
	}
	var visit func(int)
	visit = func(n int) {
		g.Reachable[n] = true
		g.Blocks[n].Reachable = true
		for _, next := range g.Blocks[n].Successors {
			if !g.Reachable[next] {
				visit(next)
			}
		}
		g.Postorder = append(g.Postorder, n)
	}
	visit(1)
	for i := len(g.Postorder) - 1; i >= 0; i-- {
		g.ReversePostorder = append(g.ReversePostorder, g.Postorder[i])
	}
	for _, n := range g.ReversePostorder {
		g.Blocks[n].Dom = cloneSet(g.Reachable)
	}
	g.Blocks[1].Dom = Set[int]{1: true}
	for {
		changed := false
		for _, n := range g.ReversePostorder[1:] {
			var dom Set[int]
			for _, pred := range g.Blocks[n].Predecessors {
				if !g.Reachable[pred] {
					continue
				}
				if dom == nil {
					dom = cloneSet(g.Blocks[pred].Dom)
				} else {
					intersectInto(dom, g.Blocks[pred].Dom)
				}
			}
			dom[n] = true
			if !equalSet(dom, g.Blocks[n].Dom) {
				g.Blocks[n].Dom = dom
				changed = true
			}
		}
		if !changed {
			break
		}
	}
	for _, b := range g.Blocks[1:] {
		if !b.Reachable || b.Number == 1 {
			continue
		}
		best := 0
		for d := range b.Dom {
			if d != b.Number && (best == 0 || len(g.Blocks[d].Dom) > len(g.Blocks[best].Dom)) {
				best = d
			}
		}
		b.IDom = best
	}
	for _, h := range g.Blocks[1:] {
		if !h.Reachable {
			continue
		}
		loop := &Loop{Header: h.Number, Blocks: Set[int]{h.Number: true}, Exits: Set[int]{}, Outside: Set[int]{}}
		for _, t := range g.Blocks[1:] {
			if !t.Reachable || !t.Dom[h.Number] {
				continue
			}
			for _, next := range t.Successors {
				if next == h.Number {
					loop.Latches = append(loop.Latches, t.Number)
					loop.Blocks[t.Number] = true
					break
				}
			}
		}
		if len(loop.Latches) == 0 {
			continue
		}
		queue := append([]int{}, loop.Latches...)
		for head := 0; head < len(queue); head++ {
			n := queue[head]
			if n == h.Number {
				continue
			}
			for _, pred := range g.Blocks[n].Predecessors {
				if g.Reachable[pred] && !loop.Blocks[pred] {
					loop.Blocks[pred] = true
					queue = append(queue, pred)
				}
			}
		}
		for n := range loop.Blocks {
			b := g.Blocks[n]
			if g.Instructions[b.Last].Kind == "return" {
				loop.Exits[n] = true
			}
			for _, next := range b.Successors {
				if !loop.Blocks[next] {
					loop.Exits[n] = true
					loop.Outside[next] = true
				}
			}
		}
		g.Loops = append(g.Loops, loop)
	}
	for _, loop := range g.Loops {
		for _, other := range g.Loops {
			if other.Blocks[loop.Header] {
				loop.Depth++
			}
		}
		for b := range loop.Blocks {
			g.Blocks[b].Depth++
		}
	}
	return g
}

package main

type Definition struct {
	Variable string
	Number   int
}
type CopyPair struct{ Destination, Source string }
type Flow[T comparable] struct {
	In, Out, Before map[int]Set[T]
	Iterations      int
}
type DataFlow struct {
	Graph                                  *CFG
	Reaching                               Flow[Definition]
	Expressions                            Flow[Expression]
	Copies                                 Flow[CopyPair]
	LiveIn, LiveOut, LiveBefore, LiveAfter map[int]Set[string]
	LiveIterations                         int
}

func reachingTransfer(s *Instruction, number int, state Set[Definition]) Set[Definition] {
	out := cloneSet(state)
	if x := s.definition(); x != "" {
		for d := range out {
			if d.Variable == x {
				delete(out, d)
			}
		}
		out[Definition{x, number}] = true
	}
	return out
}
func liveTransfer(s *Instruction, state Set[string]) Set[string] {
	out := cloneSet(state)
	delete(out, s.definition())
	for _, v := range s.used() {
		out[v] = true
	}
	return out
}
func expressionTransfer(s *Instruction, number int, state Set[Expression]) Set[Expression] {
	out := cloneSet(state)
	if expression, ok := s.expression(); ok {
		out[expression] = true
	}
	for expression := range out {
		if s.Kind == "store" && expression.Kind == "load" && expression.Operator == s.Name || s.Kind == "call" && expression.Kind == "load" || s.definition() != "" && expression.uses(s.definition()) {
			delete(out, expression)
		}
	}
	return out
}
func copyTransfer(s *Instruction, number int, state Set[CopyPair]) Set[CopyPair] {
	out := cloneSet(state)
	if x := s.definition(); x != "" {
		for pair := range out {
			if pair.Destination == x || pair.Source == x {
				delete(out, pair)
			}
		}
	}
	if s.Kind == "copy" && !s.A.IsConstant && s.Destination != s.A.Variable {
		out[CopyPair{s.Destination, s.A.Variable}] = true
	}
	return out
}
func forward[T comparable](g *CFG, universe, entry Set[T], union bool, transfer func(*Instruction, int, Set[T]) Set[T]) Flow[T] {
	flow := Flow[T]{In: map[int]Set[T]{}, Out: map[int]Set[T]{}, Before: map[int]Set[T]{}}
	for n := range g.Reachable {
		flow.Out[n] = cloneSet(universe)
	}
	for {
		flow.Iterations++
		changed := false
		for _, n := range g.ReversePostorder {
			state := Set[T]{}
			first := true
			for _, pred := range g.Blocks[n].Predecessors {
				if !g.Reachable[pred] {
					continue
				}
				if union {
					unionInto(state, flow.Out[pred])
				} else if first {
					state = cloneSet(flow.Out[pred])
					first = false
				} else {
					intersectInto(state, flow.Out[pred])
				}
			}
			if n == 1 {
				if union {
					unionInto(state, entry)
				} else {
					state = Set[T]{}
				}
			}
			flow.In[n] = cloneSet(state)
			b := g.Blocks[n]
			for i := b.First; i <= b.Last; i++ {
				state = transfer(g.Instructions[i], i, state)
			}
			if !equalSet(state, flow.Out[n]) {
				flow.Out[n] = state
				changed = true
			}
		}
		if !changed {
			break
		}
	}
	for _, b := range g.Blocks[1:] {
		if !b.Reachable {
			continue
		}
		state := cloneSet(flow.In[b.Number])
		for n := b.First; n <= b.Last; n++ {
			flow.Before[n] = cloneSet(state)
			state = transfer(g.Instructions[n], n, state)
		}
	}
	return flow
}
func newDataFlow(g *CFG) *DataFlow {
	d := &DataFlow{Graph: g, LiveIn: map[int]Set[string]{}, LiveOut: map[int]Set[string]{}, LiveBefore: map[int]Set[string]{}, LiveAfter: map[int]Set[string]{}}
	expressions := Set[Expression]{}
	copies := Set[CopyPair]{}
	parameters := Set[Definition]{}
	for _, name := range g.Function.Parameters {
		parameters[Definition{name, 0}] = true
	}
	for n, s := range g.Instructions[1:] {
		if !g.Reachable[g.BlockOf[n+1]] {
			continue
		}
		if e, ok := s.expression(); ok {
			expressions[e] = true
		}
		if s.Kind == "copy" && !s.A.IsConstant && s.Destination != s.A.Variable {
			copies[CopyPair{s.Destination, s.A.Variable}] = true
		}
	}
	d.Reaching = forward(g, Set[Definition]{}, parameters, true, reachingTransfer)
	d.Expressions = forward(g, expressions, Set[Expression]{}, false, expressionTransfer)
	d.Copies = forward(g, copies, Set[CopyPair]{}, false, copyTransfer)
	for n := range g.Reachable {
		d.LiveIn[n] = Set[string]{}
	}
	for {
		d.LiveIterations++
		changed := false
		for _, n := range g.Postorder {
			state := Set[string]{}
			for _, next := range g.Blocks[n].Successors {
				unionInto(state, d.LiveIn[next])
			}
			d.LiveOut[n] = cloneSet(state)
			b := g.Blocks[n]
			for i := b.Last; i >= b.First; i-- {
				state = liveTransfer(g.Instructions[i], state)
			}
			if !equalSet(state, d.LiveIn[n]) {
				d.LiveIn[n] = state
				changed = true
			}
		}
		if !changed {
			break
		}
	}
	for _, b := range g.Blocks[1:] {
		if !b.Reachable {
			continue
		}
		state := cloneSet(d.LiveOut[b.Number])
		for n := b.Last; n >= b.First; n-- {
			d.LiveAfter[n] = cloneSet(state)
			state = liveTransfer(g.Instructions[n], state)
			d.LiveBefore[n] = cloneSet(state)
		}
	}
	return d
}

package main

import (
	"fmt"
	"os"
	"sort"
	"strconv"
	"strings"
)

var passOrder = []string{"constprop", "copyprop", "cse", "dce", "licm", "unreachable"}

type PassResult struct {
	Count   int
	Records []string
}

func constantPropagation(f *Function, g *CFG, d *DataFlow) PassResult {
	records := []string{}
	replacements := map[int][]CodeLine{}
	for _, b := range g.Blocks[1:] {
		if !b.Reachable {
			continue
		}
		for n := b.First; n <= b.Last; n++ {
			old := g.Instructions[n]
			copy := *old
			changed := false
			for _, a := range copy.operands() {
				if a.IsConstant {
					continue
				}
				name := a.Variable
				found, valid := false, true
				value := int64(0)
				for definition := range d.Reaching.Before[n] {
					if definition.Variable != name {
						continue
					}
					if definition.Number == 0 {
						valid = false
						break
					}
					source := g.Instructions[definition.Number]
					if source.Kind != "copy" || !source.A.IsConstant {
						valid = false
						break
					}
					if found && value != source.A.Constant {
						valid = false
						break
					}
					found = true
					value = source.A.Constant
				}
				if found && valid {
					*a = constant(value)
					records = append(records, fmt.Sprintf("#%d: %s -> %d", n, name, value))
					changed = true
				}
			}
			foldedInstruction, fold := folded(&copy)
			if fold {
				changed = true
				if copy.Kind == "if" {
					if foldedInstruction == nil {
						records = append(records, fmt.Sprintf("#%d: delete %s", n, copy.String()))
					} else {
						records = append(records, fmt.Sprintf("#%d: fold %s", n, foldedInstruction.String()))
					}
				} else {
					records = append(records, fmt.Sprintf("#%d: fold %s", n, foldedInstruction.String()))
				}
			}
			if changed {
				if foldedInstruction == nil {
					replacements[n] = nil
				} else {
					replacements[n] = []CodeLine{instructionLine(foldedInstruction)}
				}
			}
		}
	}
	rewrite(f, replacements, nil)
	return PassResult{len(records), records}
}
func copyPropagation(f *Function, g *CFG, d *DataFlow) PassResult {
	records := []string{}
	replacements := map[int][]CodeLine{}
	for _, b := range g.Blocks[1:] {
		if !b.Reachable {
			continue
		}
		for n := b.First; n <= b.Last; n++ {
			copy := *g.Instructions[n]
			changed := false
			for _, a := range copy.operands() {
				if a.IsConstant {
					continue
				}
				for pair := range d.Copies.Before[n] {
					if pair.Destination == a.Variable {
						records = append(records, fmt.Sprintf("#%d: %s -> %s", n, a.Variable, pair.Source))
						a.Variable = pair.Source
						changed = true
						break
					}
				}
			}
			if changed {
				replacements[n] = []CodeLine{instructionLine(&copy)}
			}
		}
	}
	rewrite(f, replacements, nil)
	return PassResult{len(records), records}
}

type CSEGroup struct {
	Expression Expression
	Candidates []int
}

func commonSubexpressions(f *Function, g *CFG, d *DataFlow) PassResult {
	groups := []*CSEGroup{}
	byExpression := map[Expression]*CSEGroup{}
	for _, b := range g.Blocks[1:] {
		if !b.Reachable {
			continue
		}
		for n := b.First; n <= b.Last; n++ {
			e, ok := g.Instructions[n].expression()
			if !ok || !d.Expressions.Before[n][e] {
				continue
			}
			group := byExpression[e]
			if group == nil {
				group = &CSEGroup{Expression: e}
				byExpression[e] = group
				groups = append(groups, group)
			}
			group.Candidates = append(group.Candidates, n)
		}
	}
	replacements := map[int][]CodeLine{}
	records := []string{}
	count := 0
	for _, group := range groups {
		candidates := Set[int]{}
		sources := Set[int]{}
		for _, n := range group.Candidates {
			candidates[n] = true
		}
		computes := func(n int) bool {
			e, ok := g.Instructions[n].expression()
			return ok && e == group.Expression
		}
		for _, n := range group.Candidates {
			b := g.Blocks[g.BlockOf[n]]
			found := false
			for i := n - 1; i >= b.First; i-- {
				if computes(i) {
					sources[i] = true
					found = true
					break
				}
			}
			if found {
				continue
			}
			queue := append([]int{}, b.Predecessors...)
			visited := Set[int]{}
			for len(queue) > 0 {
				p := queue[len(queue)-1]
				queue = queue[:len(queue)-1]
				if !g.Reachable[p] || visited[p] {
					continue
				}
				visited[p] = true
				block := g.Blocks[p]
				found = false
				for i := block.Last; i >= block.First; i-- {
					if computes(i) {
						sources[i] = true
						found = true
						break
					}
				}
				if !found {
					queue = append(queue, block.Predecessors...)
				}
			}
		}
		for n := range candidates {
			delete(sources, n)
		}
		temporary, edits := cseReplacements(f, g, sources, candidates)
		for n, lines := range edits {
			replacements[n] = lines
		}
		records = append(records, fmt.Sprintf("%s: %s sources=%s replaced=%s", group.Expression.String(), temporary, instructionList(sortedInts(sources)), instructionList(group.Candidates)))
		count += len(group.Candidates)
	}
	rewrite(f, replacements, nil)
	return PassResult{count, records}
}
func deadCode(f *Function, g *CFG, d *DataFlow) PassResult {
	replacements := map[int][]CodeLine{}
	records := map[int]string{}
	for _, b := range g.Blocks[1:] {
		if !b.Reachable {
			continue
		}
		live := cloneSet(d.LiveOut[b.Number])
		for n := b.Last; n >= b.First; n-- {
			s := g.Instructions[n]
			if s.Kind == "copy" && !s.A.IsConstant && s.Destination == s.A.Variable || (s.Kind == "copy" || s.Kind == "bin" || s.Kind == "load") && !live[s.Destination] {
				replacements[n] = nil
				records[n] = fmt.Sprintf("#%d: delete %s", n, s.String())
				continue
			}
			if s.Kind == "call" && s.Destination != "" && !live[s.Destination] {
				copy := *s
				copy.Destination = ""
				replacements[n] = []CodeLine{instructionLine(&copy)}
				records[n] = fmt.Sprintf("#%d: unused result %s", n, s.String())
				s = &copy
			}
			live = liveTransfer(s, live)
		}
	}
	numbers := Set[int]{}
	for n := range records {
		numbers[n] = true
	}
	lines := []string{}
	for _, n := range sortedInts(numbers) {
		lines = append(lines, records[n])
	}
	rewrite(f, replacements, nil)
	return PassResult{len(lines), lines}
}
func invariantMotion(f *Function, g *CFG, d *DataFlow) PassResult {
	loops := append([]*Loop{}, g.Loops...)
	sort.Slice(loops, func(i, j int) bool {
		if len(loops[i].Blocks) != len(loops[j].Blocks) {
			return len(loops[i].Blocks) < len(loops[j].Blocks)
		}
		return loops[i].Header < loops[j].Header
	})
	for _, loop := range loops {
		instructions := []int{}
		inside := Set[int]{}
		definitionCounts := map[string]int{}
		stores := Set[string]{}
		hasCall := false
		for _, b := range g.Blocks[1:] {
			if !loop.Blocks[b.Number] {
				continue
			}
			for n := b.First; n <= b.Last; n++ {
				instructions = append(instructions, n)
				inside[n] = true
				s := g.Instructions[n]
				if x := s.definition(); x != "" {
					definitionCounts[x]++
				}
				if s.Kind == "store" {
					stores[s.Name] = true
				}
				hasCall = hasCall || s.Kind == "call"
			}
		}
		marked := Set[int]{}
		order := []int{}
		for {
			changed := false
			for _, n := range instructions {
				if marked[n] {
					continue
				}
				s := g.Instructions[n]
				if s.Kind != "copy" && s.Kind != "bin" && s.Kind != "load" {
					continue
				}
				if s.Kind == "load" && (hasCall || stores[s.Name]) {
					continue
				}
				invariant := true
				for _, v := range s.used() {
					definitions := []Definition{}
					hasInside := false
					for def := range d.Reaching.Before[n] {
						if def.Variable == v {
							definitions = append(definitions, def)
							hasInside = hasInside || inside[def.Number]
						}
					}
					if hasInside && (len(definitions) != 1 || !marked[definitions[0].Number]) {
						invariant = false
						break
					}
				}
				if invariant {
					marked[n] = true
					order = append(order, n)
					changed = true
				}
			}
			if !changed {
				break
			}
		}
		moves := []int{}
		moved := Set[int]{}
		for _, n := range order {
			s := g.Instructions[n]
			x := s.definition()
			if definitionCounts[x] != 1 || d.LiveIn[loop.Header][x] {
				continue
			}
			block := g.BlockOf[n]
			dominates := true
			for exit := range loop.Exits {
				dominates = dominates && g.Blocks[exit].Dom[block]
			}
			dangerous := s.Kind == "load" || s.Kind == "bin" && (s.Operator == "/" || s.Operator == "%") && (!s.B.IsConstant || s.B.Constant == 0)
			outsideDead := !dangerous
			for outside := range loop.Outside {
				outsideDead = outsideDead && !d.LiveIn[outside][x]
			}
			if !dominates && !outsideDead {
				continue
			}
			dependencies := true
			for _, v := range s.used() {
				for def := range d.Reaching.Before[n] {
					if def.Variable == v && inside[def.Number] && !moved[def.Number] {
						dependencies = false
					}
				}
			}
			if dependencies {
				moves = append(moves, n)
				moved[n] = true
			}
		}
		if len(moves) > 0 {
			destination := hoist(f, g, loop, moves)
			return PassResult{len(moves), []string{fmt.Sprintf("B%d: hoist %s to %s", loop.Header, instructionList(moves), destination)}}
		}
	}
	return PassResult{}
}
func applyPass(name string, f *Function) PassResult {
	g := newCFG(f)
	d := newDataFlow(g)
	switch name {
	case "constprop":
		return constantPropagation(f, g, d)
	case "copyprop":
		return copyPropagation(f, g, d)
	case "cse":
		return commonSubexpressions(f, g, d)
	case "dce":
		return deadCode(f, g, d)
	case "licm":
		return invariantMotion(f, g, d)
	case "unreachable":
		records := removeUnreachable(f, g)
		return PassResult{len(records), records}
	}
	panic("unknown pass")
}
