func main() {
	original := parseProgram()
	optimized := cloneProgram(original)
	parameters := readLines("input/params.txt")
	registers := int(integer(strings.Fields(parameters[0])[1]))
	enabled := Set[string]{}
	for _, name := range strings.Fields(parameters[1])[1:] {
		enabled[name] = true
	}
	maxRounds := int(integer(strings.Fields(parameters[2])[1]))
	passes := []string{}
	for _, name := range passOrder {
		if enabled[name] {
			passes = append(passes, name)
		}
	}
	analysis := append([]string{"== call graph (original) =="}, callGraphLines(original, callGraph(original))...)
	for _, f := range original.Functions {
		analysis = append(analysis, analysisLines(f, "original")...)
	}
	passLines := []string{}
	totals := map[string]int{}
	for _, f := range optimized.Functions {
		before := len(newCFG(f).Instructions) - 1
		passLines = append(passLines, "== "+f.Name+" ==")
		rounds := 0
		for round := 1; round <= maxRounds; round++ {
			rounds = round
			parts := []string{}
			records := []string{}
			changed := 0
			for _, name := range passes {
				result := applyPass(name, f)
				parts = append(parts, fmt.Sprintf("%s=%d", name, result.Count))
				changed += result.Count
				totals[name] += result.Count
				for _, record := range result.Records {
					records = append(records, "  "+name+" "+record)
				}
			}
			passLines = append(passLines, fmt.Sprintf("round %d: %s", round, strings.Join(parts, " ")))
			passLines = append(passLines, records...)
			if changed == 0 {
				break
			}
		}
		passLines = append(passLines, fmt.Sprintf("result: rounds=%d instructions=%d->%d", rounds, before, len(newCFG(f).Instructions)-1))
	}
	graph := callGraph(optimized)
	analysis = append(analysis, "== call graph (optimized) ==")
	analysis = append(analysis, callGraphLines(optimized, graph)...)
	removed := []string{}
	kept := []*Function{}
	for _, f := range optimized.Functions {
		if enabled["unreachable"] && !graph.Reachable[f.Name] {
			removed = append(removed, f.Name)
		} else {
			kept = append(kept, f)
		}
	}
	optimized.Functions = kept
	for _, f := range optimized.Functions {
		analysis = append(analysis, analysisLines(f, "optimized")...)
	}
	passLines = append(passLines, "== program ==", "removed functions: "+list(removed), "== total ==")
	parts := []string{}
	for _, name := range passes {
		parts = append(parts, fmt.Sprintf("%s=%d", name, totals[name]))
	}
	passLines = append(passLines, strings.Join(parts, " "))
	allocated := &Program{Arrays: append([]Array{}, optimized.Arrays...)}
	allocation := []string{}
	for _, f := range optimized.Functions {
		result, lines := allocationLines(f, registers)
		allocated.Functions = append(allocated.Functions, result)
		allocation = append(allocation, lines...)
	}
	inputs := readLines("input/input.txt")
	runs := [][]int64{}
	for _, line := range inputs[1 : int(integer(inputs[0]))+1] {
		words := strings.Fields(line)
		run := []int64{}
		for _, word := range words[1:] {
			run = append(run, integer(word))
		}
		runs = append(runs, run)
	}
	if err := os.MkdirAll("output", 0755); err != nil {
		panic(err)
	}
	save("optimized.tac", programLines(optimized))
	save("analysis.txt", analysis)
	save("passes.txt", passLines)
	save("regalloc.txt", allocation)
	save("comparison.txt", comparisons(original, optimized, allocated, runs))
}

package main

import "fmt"

func instructionLine(s *Instruction) CodeLine { return CodeLine{Instruction: s} }
func rewrite(f *Function, replacements map[int][]CodeLine, insertions map[int][]CodeLine) {
	out := []CodeLine{}
	number := 0
	for i, line := range f.Code {
		out = append(out, insertions[i]...)
		if line.Instruction != nil {
			number++
			if replacement, found := replacements[number]; found {
				out = append(out, replacement...)
				continue
			}
		}
		out = append(out, line)
	}
	out = append(out, insertions[len(f.Code)]...)
	f.Code = out
}
func folded(s *Instruction) (*Instruction, bool) {
	if s.Kind != "bin" && s.Kind != "if" {
		return s, false
	}
	a, b := s.A, s.B
	if a.IsConstant && b.IsConstant {
		if (s.Operator == "/" || s.Operator == "%") && b.Constant == 0 {
			return s, false
		}
		value := calculate(s.Operator, a.Constant, b.Constant)
		if s.Kind == "if" {
			if value != 0 {
				return &Instruction{Kind: "goto", Name: s.Name}, true
			}
			return nil, true
		}
		if value >= -2147483648 && value <= 2147483647 {
			return &Instruction{Kind: "copy", Destination: s.Destination, A: constant(value)}, true
		}
		return s, false
	}
	if s.Kind != "bin" || a.IsConstant == b.IsConstant {
		return s, false
	}
	replacement := Operand{}
	changed := true
	switch {
	case s.Operator == "+" && (a.IsConstant && a.Constant == 0 || b.IsConstant && b.Constant == 0):
		if a.IsConstant {
			replacement = b
		} else {
			replacement = a
		}
	case s.Operator == "-" && b.IsConstant && b.Constant == 0:
		replacement = a
	case s.Operator == "*" && (a.IsConstant && a.Constant == 1 || b.IsConstant && b.Constant == 1):
		if a.IsConstant {
			replacement = b
		} else {
			replacement = a
		}
	case s.Operator == "/" && b.IsConstant && b.Constant == 1:
		replacement = a
	case s.Operator == "*" && (a.IsConstant && a.Constant == 0 || b.IsConstant && b.Constant == 0):
		replacement = constant(0)
	default:
		changed = false
	}
	if !changed {
		return s, false
	}
	return &Instruction{Kind: "copy", Destination: s.Destination, A: replacement}, true
}
func cseReplacements(f *Function, g *CFG, sources, candidates Set[int]) (string, map[int][]CodeLine) {
	f.TemporarySerial++
	temporary := fmt.Sprintf("_t%d", f.TemporarySerial)
	replacements := map[int][]CodeLine{}
	for n := range sources {
		old := g.Instructions[n]
		copy := *old
		copy.Destination = temporary
		replacements[n] = []CodeLine{instructionLine(&copy), instructionLine(&Instruction{Kind: "copy", Destination: old.Destination, A: Operand{Variable: temporary}})}
	}
	for n := range candidates {
		replacements[n] = []CodeLine{instructionLine(&Instruction{Kind: "copy", Destination: g.Instructions[n].Destination, A: Operand{Variable: temporary}})}
	}
	return temporary, replacements
}
func hoist(f *Function, g *CFG, loop *Loop, moves []int) string {
	header := g.Blocks[loop.Header]
	outside := []int{}
	for _, pred := range header.Predecessors {
		if !loop.Blocks[pred] {
			outside = append(outside, pred)
		}
	}
	replacements := map[int][]CodeLine{}
	instructions := []CodeLine{}
	for _, n := range moves {
		replacements[n] = nil
		instructions = append(instructions, instructionLine(g.Instructions[n]))
	}
	position := 0
	destination := ""
	insertion := instructions
	if loop.Header != 1 && len(outside) == 1 && len(g.Blocks[outside[0]].Successors) == 1 && g.Blocks[outside[0]].Successors[0] == loop.Header {
		preheader := g.Blocks[outside[0]]
		last := g.Instructions[preheader.Last]
		position = g.Positions[preheader.Last]
		if last.Kind != "goto" && last.Kind != "if" {
			position++
		}
		destination = fmt.Sprintf("B%d", preheader.Number)
	} else {
		f.PreheaderSerial++
		label := fmt.Sprintf("_p%d", f.PreheaderSerial)
		position = header.Start
		insertion = append([]CodeLine{{Label: label}}, instructions...)
		destination = "new " + label
		labels := Set[string]{}
		for _, name := range header.Labels {
			labels[name] = true
		}
		for _, pred := range outside {
			n := g.Blocks[pred].Last
			old := g.Instructions[n]
			if (old.Kind == "goto" || old.Kind == "if") && labels[old.Name] {
				copy := *old
				copy.Name = label
				replacements[n] = []CodeLine{instructionLine(&copy)}
			}
		}
	}
	rewrite(f, replacements, map[int][]CodeLine{position: insertion})
	return destination
}
func removeUnreachable(f *Function, g *CFG) []string {
	records := []string{}
	deleted := Set[int]{}
	for _, b := range g.Blocks[1:] {
		if !b.Reachable {
			records = append(records, fmt.Sprintf("remove block B%d", b.Number))
			for i := b.Start; i < b.End; i++ {
				deleted[i] = true
			}
		}
	}
	remaining := []CodeLine{}
	for i, line := range f.Code {
		if !deleted[i] {
			remaining = append(remaining, line)
		}
	}
	jumps := Set[int]{}
	for i, line := range remaining {
		s := line.Instruction
		if s == nil || s.Kind != "goto" && s.Kind != "if" {
			continue
		}
		for j := i + 1; j < len(remaining) && remaining[j].Instruction == nil; j++ {
			if remaining[j].Label == s.Name {
				jumps[s.Number] = true
				break
			}
		}
	}
	for _, n := range sortedInts(jumps) {
		records = append(records, fmt.Sprintf("remove jump #%d", n))
	}
	withoutJumps := []CodeLine{}
	targets := Set[string]{}
	for _, line := range remaining {
		s := line.Instruction
		if s != nil && jumps[s.Number] {
			continue
		}
		withoutJumps = append(withoutJumps, line)
		if s != nil && (s.Kind == "goto" || s.Kind == "if") {
			targets[s.Name] = true
		}
	}
	f.Code = nil
	for _, line := range withoutJumps {
		if line.Instruction == nil && !targets[line.Label] {
			records = append(records, "remove label "+line.Label)
		} else {
			f.Code = append(f.Code, line)
		}
	}
	return records
}

package main

import (
	"math/big"
)

type PotentialSpill struct {
	Name   string
	Degree int
}
type Allocation struct {
	Nodes               []string
	Neighbors, Partners map[string]Set[string]
	Costs               map[string]*big.Int
	Simplify            []string
	Potential           []PotentialSpill
	Registers           map[string]int
	Spills              Set[string]
	Edges               int
}

func allocate(g *CFG, d *DataFlow, k int) *Allocation {
	nodes := Set[string]{}
	for _, name := range g.Function.Parameters {
		nodes[name] = true
	}
	for _, b := range g.Blocks[1:] {
		if !b.Reachable {
			continue
		}
		for n := b.First; n <= b.Last; n++ {
			s := g.Instructions[n]
			if x := s.definition(); x != "" {
				nodes[x] = true
			}
			for _, v := range s.used() {
				nodes[v] = true
			}
		}
	}
	a := &Allocation{Nodes: sortedStrings(nodes), Neighbors: map[string]Set[string]{}, Partners: map[string]Set[string]{}, Costs: map[string]*big.Int{}, Registers: map[string]int{}, Spills: Set[string]{}}
	for _, v := range a.Nodes {
		a.Neighbors[v] = Set[string]{}
		a.Partners[v] = Set[string]{}
		a.Costs[v] = new(big.Int)
	}
	edge := func(x, y string) {
		if x == y || !nodes[x] || !nodes[y] {
			return
		}
		a.Neighbors[x][y] = true
		a.Neighbors[y][x] = true
	}
	for _, b := range g.Blocks[1:] {
		if !b.Reachable {
			continue
		}
		live := cloneSet(d.LiveOut[b.Number])
		weight := new(big.Int).Exp(big.NewInt(10), big.NewInt(int64(b.Depth)), nil)
		for n := b.Last; n >= b.First; n-- {
			s := g.Instructions[n]
			if x := s.definition(); x != "" {
				for v := range live {
					if s.Kind == "copy" && !s.A.IsConstant && v == s.A.Variable {
						continue
					}
					edge(x, v)
				}
				a.Costs[x].Add(a.Costs[x], weight)
			}
			for _, v := range s.used() {
				a.Costs[v].Add(a.Costs[v], weight)
			}
			live = liveTransfer(s, live)
		}
	}
	entry := cloneSet(d.LiveIn[1])
	for _, p := range g.Function.Parameters {
		entry[p] = true
	}
	for _, p := range g.Function.Parameters {
		a.Costs[p].Add(a.Costs[p], big.NewInt(1))
		for v := range entry {
			edge(p, v)
		}
	}
	for _, line := range g.Function.Code {
		s := line.Instruction
		if s != nil && s.Kind == "copy" && !s.A.IsConstant && s.Destination != s.A.Variable && nodes[s.Destination] && nodes[s.A.Variable] {
			a.Partners[s.Destination][s.A.Variable] = true
			a.Partners[s.A.Variable][s.Destination] = true
		}
	}
	for _, v := range a.Nodes {
		a.Edges += len(a.Neighbors[v])
	}
	a.Edges /= 2
	remaining := cloneSet(nodes)
	for len(remaining) > 0 {
		degrees := map[string]int{}
		for v := range remaining {
			for neighbor := range a.Neighbors[v] {
				if remaining[neighbor] {
					degrees[v]++
				}
			}
		}
		chosen := ""
		low := false
		for _, v := range a.Nodes {
			if !remaining[v] || degrees[v] >= k {
				continue
			}
			if !low || degrees[v] < degrees[chosen] {
				chosen = v
				low = true
			}
		}
		if !low {
			for _, v := range a.Nodes {
				if !remaining[v] {
					continue
				}
				if chosen == "" {
					chosen = v
					continue
				}
				left := new(big.Int).Mul(a.Costs[v], big.NewInt(int64(degrees[chosen])))
				right := new(big.Int).Mul(a.Costs[chosen], big.NewInt(int64(degrees[v])))
				if left.Cmp(right) < 0 {
					chosen = v
				}
			}
			a.Potential = append(a.Potential, PotentialSpill{chosen, degrees[chosen]})
		}
		a.Simplify = append(a.Simplify, chosen)
		delete(remaining, chosen)
	}
	for i := len(a.Simplify) - 1; i >= 0; i-- {
		v := a.Simplify[i]
		forbidden := Set[int]{}
		for neighbor := range a.Neighbors[v] {
			if r, ok := a.Registers[neighbor]; ok {
				forbidden[r] = true
			}
		}
		chosen := -1
		for partner := range a.Partners[v] {
			if r, ok := a.Registers[partner]; ok && !forbidden[r] && (chosen < 0 || r < chosen) {
				chosen = r
			}
		}
		if chosen < 0 {
			for r := 0; r < k; r++ {
				if !forbidden[r] {
					chosen = r
					break
				}
			}
		}
		if chosen < 0 {
			a.Spills[v] = true
		} else {
			a.Registers[v] = chosen
		}
	}
	return a
}

package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

var instructionKinds = []string{"copy", "bin", "load", "store", "goto", "if", "param", "call", "return", "read", "print"}

type Operand struct {
	Variable   string
	Constant   int64
	IsConstant bool
}

func operand(text string) Operand {
	if text[0] == '-' || text[0] >= '0' && text[0] <= '9' {
		return Operand{Constant: integer(text), IsConstant: true}
	}
	return Operand{Variable: text}
}
func constant(n int64) Operand { return Operand{Constant: n, IsConstant: true} }
func (a Operand) String() string {
	if a.IsConstant {
		return strconv.FormatInt(a.Constant, 10)
	}
	return a.Variable
}
func integer(text string) int64 {
	n, err := strconv.ParseInt(text, 10, 64)
	if err != nil {
		panic(err)
	}
	return n
}

type Expression struct {
	Kind, Operator string
	A, B           Operand
}

func (e Expression) String() string {
	if e.Kind == "load" {
		return e.Operator + "[" + e.A.String() + "]"
	}
	return e.A.String() + e.Operator + e.B.String()
}
func (e Expression) uses(name string) bool {
	return !e.A.IsConstant && e.A.Variable == name || e.Kind == "bin" && !e.B.IsConstant && e.B.Variable == name
}

type Instruction struct {
	Kind, Destination, Operator, Name string
	A, B                              Operand
	HasA                              bool
	Count, Number                     int
}

func (s *Instruction) definition() string { return s.Destination }
func (s *Instruction) operands() []*Operand {
	switch s.Kind {
	case "copy", "load", "param", "print":
		return []*Operand{&s.A}
	case "bin", "if", "store":
		return []*Operand{&s.A, &s.B}
	case "return":
		if s.HasA {
			return []*Operand{&s.A}
		}
	}
	return nil
}
func (s *Instruction) used() []string {
	out := []string{}
	for _, a := range s.operands() {
		if !a.IsConstant {
			out = append(out, a.Variable)
		}
	}
	return out
}
func (s *Instruction) expression() (Expression, bool) {
	switch s.Kind {
	case "bin":
		return Expression{Kind: "bin", Operator: s.Operator, A: s.A, B: s.B}, true
	case "load":
		return Expression{Kind: "load", Operator: s.Name, A: s.A}, true
	}
	return Expression{}, false
}
func (s *Instruction) String() string {
	switch s.Kind {
	case "copy":
		return s.Destination + " = " + s.A.String()
	case "bin":
		return s.Destination + " = " + s.A.String() + " " + s.Operator + " " + s.B.String()
	case "load":
		return s.Destination + " = " + s.Name + "[" + s.A.String() + "]"
	case "store":
		return s.Name + "[" + s.A.String() + "] = " + s.B.String()
	case "goto":
		return "goto " + s.Name
	case "if":
		return "if " + s.A.String() + " " + s.Operator + " " + s.B.String() + " goto " + s.Name
	case "param", "print":
		return s.Kind + " " + s.A.String()
	case "call":
		prefix := ""
		if s.Destination != "" {
			prefix = s.Destination + " = "
		}
		return fmt.Sprintf("%scall %s %d", prefix, s.Name, s.Count)
	case "return":
		if s.HasA {
			return "return " + s.A.String()
		}
		return "return"
	case "read":
		return "read " + s.Destination
	}
	panic("unknown instruction")
}

type CodeLine struct {
	Label       string
	Instruction *Instruction
}
type Function struct {
	Name                             string
	Parameters                       []string
	Code                             []CodeLine
	TemporarySerial, PreheaderSerial int
}
type Array struct {
	Name string
	Size int
}
type Program struct {
	Arrays    []Array
	Functions []*Function
}

func cloneFunction(f *Function) *Function {
	out := *f
	out.Parameters = append([]string{}, f.Parameters...)
	out.Code = nil
	for _, line := range f.Code {
		if line.Instruction != nil {
			copy := *line.Instruction
			line.Instruction = &copy
		}
		out.Code = append(out.Code, line)
	}
	return &out
}
func cloneProgram(p *Program) *Program {
	out := &Program{Arrays: append([]Array{}, p.Arrays...)}
	for _, f := range p.Functions {
		out.Functions = append(out.Functions, cloneFunction(f))
	}
	return out
}
func readLines(path string) []string {
	data, err := os.ReadFile(path)
	if err != nil {
		panic(err)
	}
	return strings.Split(strings.TrimSuffix(string(data), "\n"), "\n")
}
func arrayOperand(text string) (string, Operand) {
	i := strings.IndexByte(text, '[')
	return text[:i], operand(text[i+1 : len(text)-1])
}
func parseProgram() *Program {
	p := &Program{}
	var f *Function
	for _, line := range readLines("input/program.tac") {
		words := strings.Fields(line)
		if len(words) == 0 || strings.HasPrefix(words[0], "#") {
			continue
		}
		if words[0] == "array" {
			p.Arrays = append(p.Arrays, Array{words[1], int(integer(words[2]))})
			continue
		}
		if words[0] == "func" {
			f = &Function{Name: words[1], Parameters: append([]string{}, words[2:]...)}
			p.Functions = append(p.Functions, f)
			continue
		}
		if words[0] == "end" {
			continue
		}
		if len(words) == 1 && strings.HasSuffix(words[0], ":") {
			f.Code = append(f.Code, CodeLine{Label: strings.TrimSuffix(words[0], ":")})
			continue
		}
		s := &Instruction{}
		switch words[0] {
		case "goto":
			s.Kind = "goto"
			s.Name = words[1]
		case "if":
			s.Kind = "if"
			s.A = operand(words[1])
			s.Operator = words[2]
			s.B = operand(words[3])
			s.Name = words[5]
		case "param", "print":
			s.Kind = words[0]
			s.A = operand(words[1])
		case "read":
			s.Kind = "read"
			s.Destination = words[1]
		case "return":
			s.Kind = "return"
			if len(words) == 2 {
				s.HasA = true
				s.A = operand(words[1])
			}
		case "call":
			s.Kind = "call"
			s.Name = words[1]
			s.Count = int(integer(words[2]))
		default:
			if strings.Contains(words[0], "[") {
				s.Kind = "store"
				s.Name, s.A = arrayOperand(words[0])
				s.B = operand(words[2])
			} else {
				s.Destination = words[0]
				if words[2] == "call" {
					s.Kind = "call"
					s.Name = words[3]
					s.Count = int(integer(words[4]))
				} else if len(words) == 5 {
					s.Kind = "bin"
					s.A = operand(words[2])
					s.Operator = words[3]
					s.B = operand(words[4])
				} else if strings.Contains(words[2], "[") {
					s.Kind = "load"
					s.Name, s.A = arrayOperand(words[2])
				} else {
					s.Kind = "copy"
					s.A = operand(words[2])
				}
			}
		}
		f.Code = append(f.Code, CodeLine{Instruction: s})
	}
	return p
}
func functionLines(f *Function) []string {
	header := "func " + f.Name
	for _, parameter := range f.Parameters {
		header += " " + parameter
	}
	out := []string{header}
	for _, line := range f.Code {
		if line.Instruction == nil {
			out = append(out, line.Label+":")
		} else {
			out = append(out, "    "+line.Instruction.String())
		}
	}
	return append(out, "end")
}
func programLines(p *Program) []string {
	out := []string{}
	for _, array := range p.Arrays {
		out = append(out, fmt.Sprintf("array %s %d", array.Name, array.Size))
	}
	for i, f := range p.Functions {
		if i > 0 || len(p.Arrays) > 0 {
			out = append(out, "")
		}
		out = append(out, functionLines(f)...)
	}
	return out
}
func calculate(op string, a, b int64) int64 {
	switch op {
	case "+":
		return a + b
	case "-":
		return a - b
	case "*":
		return a * b
	case "/":
		return a / b
	case "%":
		return a - (a/b)*b
	case "<":
		if a < b {
			return 1
		}
	case "<=":
		if a <= b {
			return 1
		}
	case ">":
		if a > b {
			return 1
		}
	case ">=":
		if a >= b {
			return 1
		}
	case "==":
		if a == b {
			return 1
		}
	case "!=":
		if a != b {
			return 1
		}
	}
	return 0
}
